let activeDocument=1,nextDocument=2;const openDocuments:OpenDocument[]=[];
function persistWorkspace(){
 try{const data=JSON.stringify({format:'tina-web-workspace-v1',activeDocument,nextDocument,documents:openDocuments.map(d=>({id:d.id,name:d.name,tsc:base64(d.bytes),analysis:d.analysis,dirty:d.dirty,zoom:d.zoom,offset:d.offset}))});if(data.length>8_000_000)throw Error('workspace too large');localStorage.setItem('tina-web-workspace-v1',data);}catch{status('Не удалось сохранить все вкладки в браузере. Сохраните важные схемы в файлы.');}
}
function resetInteraction(){selected=-1;selectedIndices.clear();wireStart=null;drag=null;pan=null;selectionBox=null;setMode('select');}
function storeActive(){const stored:OpenDocument={id:activeDocument,name,bytes:encode(doc),analysis:structuredClone(analysis),history:[...history],redo:[...redoHistory],dirty,zoom,offset:[...offset],result,lastConfig,resultProject,resultName,hReport,plotVector};const i=openDocuments.findIndex(d=>d.id===activeDocument);if(i<0)openDocuments.push(stored);else openDocuments[i]=stored;persistWorkspace();}
function documentTabs(){const holder=$('#document-tabs');if(!holder)return;holder.innerHTML=openDocuments.map(d=>`<button class="document-tab ${d.id===activeDocument?'active':''}" data-document="${d.id}" title="${esc(d.name)}">${esc(d.name)}${d.dirty?' *':''}<span data-close-document="${d.id}" title="Закрыть схему">×</span></button>`).join('');}
function loadActive(stored:OpenDocument){activeDocument=stored.id;name=stored.name;doc=decode(stored.bytes);analysis=structuredClone(stored.analysis);history=[...stored.history];redoHistory=[...stored.redo];dirty=stored.dirty;zoom=stored.zoom;offset=[...stored.offset];result=stored.result;lastConfig=stored.lastConfig;resultProject=stored.resultProject;resultName=stored.resultName;hReport=stored.hReport;plotVector=stored.plotVector;resetInteraction();resetCalculationViews();$('#title').textContent=name+(dirty?' *':'')+' — Схемный редактор';switchTab('schematic');renderProperties();documentTabs();}
function switchDocument(id:number){if(abort){status('Сначала завершите или остановите текущий расчёт.');return;}storeActive();const stored=openDocuments.find(d=>d.id===id);if(stored)loadActive(stored);persistWorkspace();}
function addDocument(loaded:Doc,title:string,config:SimulationConfig){storeActive();activeDocument=nextDocument++;name=title;doc=loaded;analysis=config;history=[];redoHistory=[];selected=-1;selectedIndices.clear();dirty=false;result=null;lastConfig=null;hReport=null;resultProject=null;resultName='';plotVector='';resetInteraction();resetCalculationViews();$('#title').textContent=name+' — Схемный редактор';switchTab('schematic');fit();renderProperties();storeActive();documentTabs();}
function closeDocument(id:number){if(abort){status('Остановите расчёт перед закрытием схемы.');return;}storeActive();const i=openDocuments.findIndex(d=>d.id===id);if(i<0)return;if(openDocuments[i].dirty&&!confirm('Закрыть схему «'+openDocuments[i].name+'» без сохранения?'))return;openDocuments.splice(i,1);if(!openDocuments.length){activeDocument=nextDocument++;doc=blank();name='Схема'+activeDocument;analysis={kind:'op'};history=[];redoHistory=[];dirty=false;result=null;lastConfig=null;hReport=null;storeActive();loadActive(openDocuments[0]);}else if(id===activeDocument)loadActive(openDocuments[Math.min(i,openDocuments.length-1)]);documentTabs();persistWorkspace();}
