const checkActions=new Set(['normal','grid','pins','values','elements','labels','toolbar','palette','panel']);
function menuItem(label:string,act?:string,key?:string){return `<button ${act?`data-action="${act}"`:'disabled title="Будет добавлено: функция пока не перенесена"'} ${act&&checkActions.has(act)?'role="menuitemcheckbox" aria-checked="false"':''}><span class="menu-check" aria-hidden="true"></span><span>${esc(label)}</span>${key?`<kbd>${esc(key)}</kbd>`:''}${act?'':'<small class="pending">будет добавлено</small>'}</button>`;}
function renderMenus(){return liveMenus.map(menu=>{const used=new Set<string>();const render=(items:typeof menu.children):string=>items.map(item=>{const [label,key]=item.label.split('\t');if(!label)return '<hr>';if(item.children.length)return `<div class="menu-submenu"><button aria-haspopup="menu"><span class="menu-check"></span>${esc(label)}<kbd>▶</kbd></button><div class="dropdown" role="menu">${render(item.children)}</div></div>`;const act=nativeActions[item.id];if(act)used.add(act);return menuItem(label,act,key);}).join('');const native=render(menu.children),extra=(menus[menu.label]??[]).filter(([,act])=>!used.has(act));return `<details><summary>${esc(menu.label)}</summary><div class="dropdown">${native}${extra.length?'<hr>'+extra.map(([label,act,key])=>menuItem(label,act,key)).join(''):''}</div></details>`;}).join('');}
function updateMenuChecks(){const checks:Record<string,boolean>={normal:true,grid,pins:pinMarkers,values:showValues,elements:showElements,labels:showLabels,toolbar:showToolbar,palette:showPalette,panel:showProps};document.querySelectorAll<HTMLElement>('[role="menuitemcheckbox"]').forEach(b=>{const on=!!checks[b.dataset.action!];b.setAttribute('aria-checked',String(on));b.querySelector('.menu-check')!.textContent=on?'✓':'';});}
