function rotatePoint(c:Component,p:Point):Point{let [x,y]=p;for(let i=0;i<(c.orientation&3);i++)[x,y]=[y,-x];return [c.x+x,c.y+y];}
function draw(){
 const cc=components(doc),ww=wires(doc);let html=ww.map(w=>`<g data-index="${w.index}"><polyline class="wire ${selectedIndices.has(w.index)||selected===w.index?'selected':''}" points="${w.points.map(p=>p.join(',')).join(' ')}"/>${w.points.slice(1).map((b,i)=>`<path class="pick" data-wire-segment="${i}" d="M${w.points[i].join(',')}L${b.join(',')}"/>`).join('')}</g>`).join('');
 // Black dots denote real branches, not every component terminal.
 const candidates=new Map<string,Point>();for(const w of ww)for(const p of w.points)candidates.set(p.join(','),p);for(const c of cc)for(const p of pins(c))candidates.set(p.join(','),p);
 for(const p of candidates.values()){const dirs=new Set<string>();for(const w of ww)for(let i=1;i<w.points.length;i++){const a=w.points[i-1],b=w.points[i],dx=b[0]-a[0],dy=b[1]-a[1];if((p[0]-a[0])*dy!==(p[1]-a[1])*dx||p[0]<Math.min(a[0],b[0])||p[0]>Math.max(a[0],b[0])||p[1]<Math.min(a[1],b[1])||p[1]>Math.max(a[1],b[1]))continue;for(const q of [a,b])if(q[0]!==p[0]||q[1]!==p[1])dirs.add([Math.sign(q[0]-p[0]),Math.sign(q[1]-p[1])].join(','));}const count=cc.filter(c=>pins(c).some(q=>q[0]===p[0]&&q[1]===p[1])).length;if(dirs.size+count>=3)html+=`<circle cx="${p[0]}" cy="${p[1]}" r="1.8" fill="#222"/>`;}
 for(const c of showElements?cc:[]){let pp:Point[];try{pp=pins(c);}catch{continue;}const label=labelGeometry(c);html+=`<g data-index="${c.index}"><g class="symbol ${selectedIndices.has(c.index)||selected===c.index?'selected':''}" style="color:${selectedIndices.has(c.index)||selected===c.index?'#ff0000':'#008000'}" transform="translate(${c.x} ${c.y}) rotate(${-90*(c.orientation&3)}) scale(${c.mirrored?-1:1} 1)">${symbol(c.kind)}<rect x="${['NPN','PNP'].includes(c.kind)?-20:-14}" y="-27" width="${['NPN','PNP'].includes(c.kind)?42:62}" height="76" fill="transparent" stroke="none"/></g>${pinMarkers?pp.map(p=>`<path class="pin" d="M${p[0]-1.1},${p[1]-1.1}l2.2,2.2m-2.2,0l2.2,-2.2"/>`).join(''):''}${c.label&&(showLabels||showValues)?`<text data-label-index="${c.index}" class="label ${c.kind==='AM'?'meterlabel':''}" x="${label.x}" y="${label.y}" dominant-baseline="text-before-edge" transform="rotate(${label.angle} ${label.x} ${label.y})">${showLabels?esc(c.label):''}${showValues?(c.model?' '+esc(c.model):c.value!==undefined?' '+esc(eng(c.value)):''):''}</text>`:''}</g>`;}
 for(const t of texts(doc)){const px=t.size*4/3;html+=`<g data-index="${t.index}" class="annotation" style="font-family:${esc(JSON.stringify(t.font))};font-size:${px}px;font-weight:${t.style&1?'bold':'normal'};font-style:${t.style&2?'italic':'normal'};text-decoration:${[t.style&4?'underline':'',t.style&8?'line-through':''].filter(Boolean).join(' ')};fill:${selected===t.index?'#ff0000':t.cssColor}"><text x="${t.x+8}" y="${t.y+px*.85}">${t.lines.map((line,i)=>`<tspan x="${t.x+8}" dy="${i?px*1.15:0}">${esc(line)||'&#160;'}</tspan>`).join('')}</text></g>`;}
 if(selectionBox){const a=selectionBox.start,b=selectionBox.end;html+=`<rect x="${Math.min(a[0],b[0])}" y="${Math.min(a[1],b[1])}" width="${Math.abs(b[0]-a[0])}" height="${Math.abs(b[1]-a[1])}" fill="#0000800b" stroke="#000080" stroke-width=".5" stroke-dasharray="3 2"/>`;}if(wireStart)html+=`<circle cx="${wireStart[0]}" cy="${wireStart[1]}" r="4" fill="none" stroke="#d68d14"/>`;
 $('#drawing').innerHTML=html;const field=$('#field');field.setAttribute('transform',`translate(${offset[0]} ${offset[1]}) scale(${zoom})`);const rect=$('#gridRect');rect.setAttribute('x',String(-offset[0]/zoom));rect.setAttribute('y',String(-offset[1]/zoom));rect.setAttribute('width',String(sheet.clientWidth/zoom));rect.setAttribute('height',String(sheet.clientHeight/zoom));rect.style.display=grid?'':'none';$('#counts').textContent=`${cc.length} эл. · ${ww.length} проводов${texts(doc).length?' · '+texts(doc).length+' надп.':''}`;
 updateMenuChecks();
 const z=$<HTMLSelectElement>('#zoom');if(![...z.options].some(o=>Number(o.value)===Math.round(zoom*100))){let o=z.querySelector('[data-custom]');o?.remove();o=document.createElement('option');o.setAttribute('data-custom','');(o as HTMLOptionElement).value=String(Math.round(zoom*100));o.textContent=Math.round(zoom*100)+'%';z.append(o);}z.value=String(Math.round(zoom*100));
}
function fit(){const ps:Point[]=[];for(const t of texts(doc)){const px=t.size*4/3;ps.push([t.x,t.y],[t.x+Math.max(...t.lines.map(l=>l.length),1)*px*.7+16,t.y+t.lines.length*px*1.15]);}for(const c of components(doc))ps.push([c.x-80,c.y-65],[c.x+120,c.y+70]);for(const w of wires(doc))ps.push(...w.points);if(!ps.length)return;const lo=[Math.min(...ps.map(p=>p[0])),Math.min(...ps.map(p=>p[1]))],hi=[Math.max(...ps.map(p=>p[0])),Math.max(...ps.map(p=>p[1]))];zoom=Math.max(.3,Math.min(2.25,(sheet.clientWidth-60)/Math.max(1,hi[0]-lo[0]),(sheet.clientHeight-70)/Math.max(1,hi[1]-lo[1])));offset=[sheet.clientWidth/2-(hi[0]+lo[0])*zoom/2,sheet.clientHeight/2-(hi[1]+lo[1])*zoom/2];draw();}
function setZoom(z:number,at?:Point){z=Math.max(.3,Math.min(4,z));const p=at??[sheet.clientWidth/2,sheet.clientHeight/2],n=[(p[0]-offset[0])/zoom,(p[1]-offset[1])/zoom];offset=[p[0]-n[0]*z,p[1]-n[1]*z];zoom=z;draw();}
