function openProperties(){
 if(doc.records[selected]?.type===262){textDialog(undefined,selected);return;}
 const c=currentComponent();if(!c)return;
 showComponentProperties(doc,c.index,changes=>{
  const before=encode(doc),previousRedo=redoHistory;remember();
  try{moveComponent(doc,c.index,changes.x??c.x,changes.y??c.y,changes.orientation??c.orientation);updateComponent(doc,c.index,changes);change();}
  catch(e){Object.assign(doc,decode(before));history.pop();redoHistory=previousRedo;throw e;}
 },mutate=>{const before=encode(doc),previousRedo=redoHistory;remember();try{mutate();change();}catch(e){Object.assign(doc,decode(before));history.pop();redoHistory=previousRedo;throw e;}});
}
